export function p_fewer(a, b, c) { return [a, b, c, arguments.length]; }
export function p_more(a) { return [a, arguments.length, arguments[1]]; }
export function p_none(a) { return [typeof a, a]; }
export function p_swapped(text, count) { return [text.length, count + 1]; }
export function p_optional(a) { return a === undefined ? "none" : a.length; }
export function p_required(a) { return a === undefined ? "none" : a.length; }
export function p_default(a = 5, b = a + 1) { return [a, b]; }
export function p_rest_declared(a, b) { return [a, b]; }
export function p_rest_written(...all) { return [all.length, all, Array.isArray(all)]; }
export function p_rest_behind(a, ...more) { return [a, more]; }
export function p_object_pattern({ a, b = "default" }) { return [a, b]; }
export function p_pattern_is_string({ length, a }) { return [length, a]; }
export function p_array_pattern([a, b]) { return [a, b]; }
export function p_assigned(a) { const was = a; a = { now: "an object" }; return [was, a.now]; }
export function p_or_default(a) { a = a || {}; return typeof a; }
export function p_arguments(a) { arguments[0] = "written through arguments"; return a; }
export function p_captured(a) { const read = () => a; a = [a]; return read(); }
export function p_this(a) { return [this === undefined ? "no this" : typeof this, a]; }
export function p_same_name(a, b) { return [a, b]; }
